const input = $json.body || $json;

const supportedProviders = {
  google_sheets: {
    adapter_component_id: 'C2-A1',
    adapter_name: 'Google Sheets Write Adapter',
    adapter_family: 'data_write',
    next_action: 'execute_selected_adapter',
    write_request_type: 'google_sheets_write_request'
  },
  airtable: {
    adapter_component_id: 'C2-A2',
    adapter_name: 'Airtable Write Adapter',
    adapter_family: 'data_write',
    next_action: 'execute_selected_adapter',
    write_request_type: 'airtable_write_request'
  },
  hubspot: {
    adapter_component_id: 'C2-A3',
    adapter_name: 'HubSpot Contact Write Adapter',
    adapter_family: 'data_write',
    next_action: 'execute_selected_adapter',
    write_request_type: 'hubspot_contact_write_request'
  }
};

function baseResult(status, code, message) {
  return {
    request_id: input.request_id || null,
    router_status: status,
    selected_adapter: null,
    selected_adapter_name: null,
    adapter_family: 'data_write',
    provider: input.destination?.provider || null,
    operation: input.destination?.operation || null,
    manual_review_required: true,
    error_code: code,
    error_message: message,
    next_action: status === 'blocked'
      ? 'route_to_manual_review_and_error_log'
      : 'route_to_error_log',
    status_log_event: status === 'blocked'
      ? 'router_blocked'
      : 'router_error',
    downstream_components: status === 'blocked'
      ? ['C5-E', 'C6-G', 'C5-W']
      : ['C6-G', 'C5-W'],
    original_input: input
  };
}

if (input.upstream_status !== 'success') {
  return [{
    json: baseResult(
      'blocked',
      'UPSTREAM_VALIDATION_FAILED',
      'Upstream component failed validation. C2-A did not route to a write adapter.'
    )
  }];
}

if (!input.destination) {
  return [{
    json: baseResult(
      'error',
      'MISSING_DESTINATION',
      'Destination object is required before C2-A can select a write adapter.'
    )
  }];
}

if (!input.destination.provider) {
  return [{
    json: baseResult(
      'error',
      'MISSING_PROVIDER',
      'Destination provider is required before C2-A can select a write adapter.'
    )
  }];
}

if (!input.destination.config) {
  return [{
    json: baseResult(
      'error',
      'MISSING_DESTINATION_CONFIG',
      'Destination config is required before C2-A can prepare adapter input.'
    )
  }];
}

if (!input.record) {
  return [{
    json: baseResult(
      'error',
      'MISSING_RECORD',
      'Record payload is required before C2-A can prepare adapter input.'
    )
  }];
}

const provider = input.destination.provider;
const adapter = supportedProviders[provider];

if (!adapter) {
  return [{
    json: {
      request_id: input.request_id || null,
      router_status: 'error',
      selected_adapter: null,
      selected_adapter_name: null,
      adapter_family: 'data_write',
      provider,
      operation: input.destination.operation || null,
      manual_review_required: true,
      error_code: 'UNSUPPORTED_PROVIDER',
      error_message: `Provider ${provider} is not supported by C2-A v1.`,
      next_action: 'route_to_manual_review_and_scope_adapter_gap',
      status_log_event: 'router_error',
      downstream_components: ['C5-E', 'C6-G', 'C5-W'],
      adapter_gap: {
        provider,
        suggested_action: 'build_or_configure_adapter',
        gap_type: 'deferred_or_missing_adapter'
      },
      original_input: input
    }
  }];
}

return [{
  json: {
    request_id: input.request_id,
    router_status: 'routed',
    selected_adapter: adapter.adapter_component_id,
    selected_adapter_name: adapter.adapter_name,
    adapter_family: adapter.adapter_family,
    provider,
    operation: input.destination.operation,
    manual_review_required: false,
    error_code: null,
    error_message: null,
    next_action: adapter.next_action,
    status_log_event: 'adapter_selected',
    adapter_input: {
      adapter_component_id: adapter.adapter_component_id,
      adapter_name: adapter.adapter_name,
      adapter_family: adapter.adapter_family,
      write_request_type: adapter.write_request_type,
      request_id: input.request_id,
      source_component: input.source_component,
      operation: input.destination.operation,
      destination_config: input.destination.config,
      record: input.record,
      routing_options: input.routing_options || {}
    },
    downstream_components: [adapter.adapter_component_id, 'C5-W'],
    original_input: input
  }
}];
